import React, { useState } from 'react';
import AppLayout from '../components/AppLayout';
import { FoodCardRow, RestaurantCard, C } from '../components/UI';
import { useApp } from '../context/AppContext';
import { RESTAURANTS } from '../data/mockData';

const TABS = ['Foods', 'Restaurants'];

export default function FavoritesScreen() {
  const [activeTab, setActiveTab] = useState('Foods');
  const { savedFoodObjects, favorites } = useApp();

  const favRests = RESTAURANTS.filter(r => favorites.restaurants.includes(r.id));

  return (
    <AppLayout>
      <div style={{ padding: '20px 16px 0' }}>
        <h1 style={{ fontSize: 22, fontWeight: 800, color: '#fff', marginBottom: 16 }}>My Favourites</h1>

        {/* Tabs */}
        <div style={{ display: 'flex', gap: 0, background: '#1e1e1e', borderRadius: 10, padding: 4, marginBottom: 20 }}>
          {TABS.map(tab => (
            <button key={tab} onClick={() => setActiveTab(tab)} style={{
              flex: 1, padding: '9px 0', borderRadius: 8, border: 'none', cursor: 'pointer',
              background: activeTab === tab ? C.orange : 'transparent',
              color: activeTab === tab ? '#fff' : '#666',
              fontSize: 13, fontWeight: 700, transition: 'all 0.2s',
            }}>{tab}</button>
          ))}
        </div>
      </div>

      <div style={{ padding: '0 16px' }}>
        {activeTab === 'Foods' && (
          savedFoodObjects.length === 0
            ? <EmptyState emoji="🍽️" msg="No saved foods yet" sub="Tap the heart ♥ on any food to save it here" />
            : (
              <>
                <p style={{ fontSize: 13, color: '#666', marginBottom: 14 }}>{savedFoodObjects.length} saved food{savedFoodObjects.length !== 1 ? 's' : ''}</p>
                {savedFoodObjects.map(f => <FoodCardRow key={f.id} food={f} />)}
              </>
            )
        )}
        {activeTab === 'Restaurants' && (
          favRests.length === 0
            ? <EmptyState emoji="🏪" msg="No saved restaurants" sub="Tap the heart on a restaurant to save it" />
            : favRests.map(r => <RestaurantCard key={r.id} restaurant={r} />)
        )}
      </div>
    </AppLayout>
  );
}

function EmptyState({ emoji, msg, sub }) {
  return (
    <div style={{ textAlign: 'center', padding: '60px 20px' }}>
      <div style={{ fontSize: 52, marginBottom: 16 }}>{emoji}</div>
      <p style={{ fontSize: 16, fontWeight: 700, color: '#fff', marginBottom: 6 }}>{msg}</p>
      <p style={{ fontSize: 13, color: '#555' }}>{sub}</p>
    </div>
  );
}
